**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("macierz.txt");
    int m[6][6], r[6][6];
    for (int i = 0; i < 6; i++)
        for (int j = 0; j < 6; j++)
            plik >> m[i][j];

    // a) Obrot o 180
    for (int i = 0; i < 6; i++)
        for (int j = 0; j < 6; j++)
            r[i][j] = m[5 - i][5 - j];

    cout << "a) Obrocona o 180:" << endl;
    for (int i = 0; i < 6; i++) {
        for (int j = 0; j < 6; j++) {
            if (j > 0) cout << " ";
            cout << r[i][j];
        }
        cout << endl;
    }

    // b) Czy symetryczna 180
    bool sym = true;
    int cnt = 0;
    int fw = -1, fk = -1;
    for (int i = 0; i < 6; i++)
        for (int j = 0; j < 6; j++)
            if (m[i][j] != m[5 - i][5 - j]) {
                sym = false;
                cnt++;
                if (fw == -1) { fw = i; fk = j; }
            }

    cout << "b) Symetria 180: " << (sym ? "TAK" : "NIE") << endl;
    cout << "c) Elementy naruszajace: " << cnt << endl;
    if (fw == -1)
        cout << "d) Brak" << endl;
    else
        cout << "d) Pierwszy: (" << fw + 1 << ", " << fk + 1 << ")" << endl;
    return 0;
}
```

**Wyjasnienie**: Obrot o 180 to zamiana m[i][j] <-> m[n-1-i][n-1-j]. Macierz symetryczna 180-stopniowo spelnia m[i][j]==m[5-i][5-j] dla kazdego (i,j).

Weryfikacja:
- r[0][0] = m[5][5] = 1, r[0][1] = m[5][4] = 2, ..., r[0][5] = m[5][0] = 6 -> wiersz 1: 1 2 3 4 5 6
- r[1][0] = m[4][5] = 7, r[1][1] = m[4][4] = 8, ..., r[1][5] = m[4][0] = 12 -> wiersz 2: 7 8 9 10 11 12
- r[2][0] = m[3][5] = 13, ..., r[2][5] = m[3][0] = 18 -> wiersz 3: 13 14 15 16 17 18
- r[3][0] = m[2][5] = 18, ..., r[3][5] = m[2][0] = 13 -> wiersz 4: 18 17 16 15 14 13
- r[4][0] = m[1][5] = 12, ..., r[4][5] = m[1][0] = 7 -> wiersz 5: 12 11 10 9 8 7
- r[5][0] = m[0][5] = 6, ..., r[5][5] = m[0][0] = 1 -> wiersz 6: 6 5 4 3 2 1

Obrocona macierz == oryginalna -> TAK symetria 180, 0 naruszen.
